var recorder = new ArcShortcutRecorder
{
    Label = "切换侧栏",
    Gesture = "Ctrl+Shift+K",
    Bindings = new List<ArcShortcutBinding>
    {
        new("Ctrl+K", "打开搜索"),
        new("Ctrl+P", "打印")
    },
    WarnReserved = true
};

recorder.GestureChanged += (_, e) =>
{
    ShortcutMap.Assign("toggle-sidebar", e.Gesture, e.Replaced);
};
